{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of range')
    alloc = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_val = -1.0
        for i, s in enumerate(segments):
            if alloc[i] >= s['capacity']:
                continue
            score = s['importance'] / (alloc[i] + 1.0)
            if score > best_val:
                best_val = score
                best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = budget
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"
}
